   421	static void sf32lb52_bt_rx_worker(FAR void *arg)
   422	{
   423	  struct sf32lb52_bt_env_s *env = arg;
   424	
   425	  for (;;)
   426	    {
   427	      irqstate_t flags;
   428	      int empty_retries = 0;
   429	
   430	      for (;;)
   431	        {
   432	          size_t size;
   433	          size_t read_len;
   434	          int ret;
   435	          struct circular_buf *rx_ring;
   436	          uint32_t wr_ptr;
   437	
   438	          flags = enter_critical_section();
   439	
   440	          if (!env->queue_open || env->ipc_port == IPC_QUEUE_INVALID_HANDLE)
   441	            {
   442	              env->rx_work_pending = false;
   443	              env->rx_worker_running = false;
   444	              leave_critical_section(flags);
   445	              return;
   446	            }
   447	
   448	          leave_critical_section(flags);
   449	
   450	          up_invalidate_dcache((uintptr_t)SF32LB52_BT_RX_BUF_ADDR,
   451	                               (uintptr_t)SF32LB52_BT_RX_BUF_ADDR +
   452	                               SF32LB52_BT_RX_BUF_SIZE);
   453	
   454	          flags = enter_critical_section();
   455	
   456	          if (!env->queue_open || env->ipc_port == IPC_QUEUE_INVALID_HANDLE)
   457	            {
   458	              env->rx_work_pending = false;
   459	              env->rx_worker_running = false;
   460	              leave_critical_section(flags);
   461	              return;
   462	            }
   463	
   464	          rx_ring = (struct circular_buf *)SF32LB52_BT_RX_BUF_ADDR;
   465	          wr_ptr = rx_ring->write_idx_mirror;
   466	          size = sf32lb52_bt_ring_data_len(env->rx_read_idx_mirror,
   467	                                          wr_ptr,
   468	                                          rx_ring->buffer_size);
   469	          if (size == 0)
   470	            {
   471	              uint32_t rd_ptr = rx_ring->read_idx_mirror;
   472	              uint32_t local_rd = env->rx_read_idx_mirror;
   473	
   474	              leave_critical_section(flags);
   475	
   476	              if (empty_retries++ < 20)
   477	                {
   478	                  usleep(1000);
   479	                  continue;
   480	                }
   481	
   482	          #if SF32LB52_BT_TRACE
   483	              syslog(LOG_INFO,
   484	                "sf32lb52 bt rx empty: local=%08lx rd=%08lx wr=%08lx\n",
   485	                (unsigned long)local_rd,
   486	                (unsigned long)rd_ptr,
   487	                (unsigned long)wr_ptr);
   488	          #endif
   489	              break;
   490	            }
   491	
   492	          empty_retries = 0;
   493	
   494	          if (size > sizeof(env->data_buf))
   495	            {
   496	              size = sizeof(env->data_buf);
   497	            }
   498	
   499	          read_len = sf32lb52_bt_ring_copy(env->data_buf, rx_ring,
   500	                                           env->rx_read_idx_mirror, size);
   501	          if (read_len == 0)
   502	            {
   503	              leave_critical_section(flags);
   504	              break;
   505	            }
   506	
   507	          env->rx_read_idx_mirror = sf32lb52_bt_ring_advance(
   508	              env->rx_read_idx_mirror, read_len, rx_ring->buffer_size);
   509	          rx_ring->read_idx_mirror = env->rx_read_idx_mirror;
   510	          __DSB();
   511	
   512	          up_clean_dcache((uintptr_t)SF32LB52_BT_RX_BUF_ADDR,
   513	                          (uintptr_t)SF32LB52_BT_RX_BUF_ADDR +
   514	                          sizeof(*rx_ring));
   515	
   516	          env->rx_count++;
   517	
   518	          leave_critical_section(flags);
   519	
   520	        #if SF32LB52_BT_TRACE
   521	             syslog(LOG_INFO,
   522	               "sf32lb52 bt rx drain: len=%lu local=%08lx wr=%08lx\n",
   523	               (unsigned long)read_len,
   524	               (unsigned long)env->rx_read_idx_mirror,
   525	               (unsigned long)wr_ptr);
   526	        #endif
   527	
   528	          if (env->notify_host == NULL)
   529	            {
   530	              continue;
   531	            }
   532	
   533	          ret = env->notify_host(env->data_buf, read_len);
   534	          if (ret < 0)
   535	            {
   536	              syslog(LOG_ERR, "sf32lb52 bt rx callback: %d\n", ret);
   537	            }
   538	        }
   539	
   540	      flags = enter_critical_section();
   541	      if (!env->rx_work_pending)
   542	        {
   543	          env->rx_worker_running = false;
   544	          leave_critical_section(flags);
   545	          break;
   546	        }
   547	
   548	      env->rx_work_pending = false;
   549	      leave_critical_section(flags);
   550	    }
   551	}
